For \(x_0\in\mathbb S^{n-1}\) and \(0<\eta\le 1\), define the geodesic $\eta$-cap
$\mathcal B(x_0,\eta):=\{x\in\mathbb S^{n-1}: \mathrm{d}_{\mathrm{S}}(x,x_0)\le \eta\}$. For a distribution \(R\) on \(\mathbb S^{n-1}\) and \(\delta\in[0,1)\), the
\((\eta,\delta)\)-approximate covering number is
\begin{equation}
\mathrm{Cov}_{\eta,\delta}(R):=\min\left\{k\in \mathbb N:R\left(\bigcup_{i=1}^k \mathcal B(x_i,\eta)\right)\ge 1-\delta,
\ x_i\in\mathbb S^{n-1}
\right\}.
\end{equation}

Let \(\mu\) and \(\nu\) be probability distributions on \(\mathbb S^{n-1}\), and let
\(\Pi(\mu,\nu)\) denote the set of all couplings of \(\mu\) and \(\nu\).
For \(p\ge 1\), the geodesic Wasserstein-\(p\) distance between \(\mu\) and \(\nu\) is defined as
\begin{equation}
\mathcal W_{p,\mathrm{geo}}(\mu,\nu)
:=
\left(
\inf_{\gamma\in\Pi(\mu,\nu)}
\int_{\mathbb S^{n-1}\times\mathbb S^{n-1}}
\mathrm{d}_{\mathrm{S}}(x,y)^p\, d\gamma(x,y)
\right)^{1/p}.
\end{equation}
The corresponding geodesic Wasserstein-\(\infty\) distance is defined as
\begin{equation}
\mathcal W_{\infty,\mathrm{geo}}(\mu,\nu)
:=
\inf_{\gamma\in\Pi(\mu,\nu)}
\operatorname*{ess\,sup}_{(x,y)\sim\gamma}
\mathrm{d}_{\mathrm{S}}(x,y).
\end{equation}

\label{separation_gap}
For the noisy Gaussian one-bit model with noise level \(\sigma\), let \(f_\sigma(w)=\frac{1}{\pi}\arccos\!\left(\frac{\cos(\pi w)}{\sqrt{1+\sigma^2}}\right)\), \(w\in[0,1]\). For \(u\in(0,1)\) and \(s\in(1,1/u)\), the one-bit separation gap is defined by \(\Delta_\sigma(s,u):=f_\sigma(su)-f_\sigma(u)\). Since \(s>1\), we have \(su>u\), by the monotonicity of
\(f_\sigma\), \(\Delta_\sigma(s,u)\ge 0\).

\label{hammingdistance}
    Consider two signals $x_1,x_2\in\mathbb S^{n-1}$ defined on the unit Euclidean sphere. Define the observations of these two signals as $u=\operatorname{sign}(Ax_1+\xi)$ and $v=\operatorname{sign}(Ax_2)$. We have:
\begin{equation}
\mathbb{E}[\mathrm{d}_{\mathrm{H}}(u,v)] = \frac{1}{\pi} \arccos\left(\frac{\cos(\pi \mathrm{d}_{\mathrm{S}}(x_1,x_2))}{\sqrt{1+\sigma^2}}\right).
\end{equation}

\label{lem:near_far_test}
    Fix a reference point \(x_0\in\mathbb S^{n-1}\). Let the testing threshold be $\tau_{\eta,c,\sigma}:=\frac{f_\sigma(\eta)+f_\sigma(c\eta)}{2}$,
and define the test function
$\phi_{x_0,\eta}(y;A):=
\mathbf 1\left\{\mathrm{d}_{\mathrm{H}}\left(y,\operatorname{sign}(Ax_0)\right)\ge\tau_{\eta,c,\sigma}\right\}$.
Then the following two testing error bounds hold in the annealed sense:
\begin{equation}
    \sup_{x:\ \mathrm{d}_{\mathrm{S}}(x,x_0)\le \eta}
\Pr_{A,\xi| x}
\left(\phi_{x_0,\eta}(y;A)=1\right)
\le
\exp\left(-\frac{m}{2}\Delta_\sigma(c,\eta)^2\right),
\end{equation}

and
\begin{equation}
\sup_{x:\ \mathrm{d}_{\mathrm{S}}(x,x_0)\ge c\eta}\Pr_{A,\xi| x}
\left(\phi_{x_0,\eta}(y;A)=0\right)
\le
\exp\left(-\frac{m}{2}\Delta_\sigma(c,\eta)^2\right).
\end{equation}
Here the probability is taken with respect to the joint randomness of the measurement matrix \(A\) and the noise \(\xi\), conditional on the fixed reference point \(x\). Hence the result is annealed, in the sense that the probability is averaged over the measurement matrix \(A\), rather than a conditional in \(A\) bound for a fixed realization of \(A\).

\label{lemma:orup}
Let \(Q\) be a probability distribution on \(\mathbb S^{n-1}\). Assume that there exist centers \(x_1,\ldots,x_N\in\mathbb S^{n-1}\) such that, with $ \mathcal C_j:=\{x\in\mathbb S^{n-1}: \mathrm{d}_{\mathrm{S}}(x,x_j)\le \eta\}, G:=\bigcup_{j=1}^N\mathcal C_j. $
Fix \(\alpha\in(0,\frac{1}{2})\), and assume that
\begin{equation}
    Q=(1-\alpha)Q_g+\alpha Q_b \qquad Q_g(G)=1, 
\end{equation}


Here \(Q_g\) denotes a covered good component of \(Q\), of mixture weight
\(1-\alpha\), contained in the high-probability region \(G\). Let $x^*\sim Q_g$, and let
$\widehat x\sim Q(\cdot| y,A)$
be the posterior sampling estimator based on the same distribution \(Q\). Suppose \(0<\eta<\frac{1}{2}\), and \(c\in(1,\frac{1}{\eta}-1)\). Then we have:
\begin{equation}
\Pr_{x^*\sim Q_g,A,\xi,\widehat{x}}\left(\mathrm{d}_{\mathrm{S}}(x^*,\widehat x)\ge(c+1)\eta\right)
\le
\frac{1}{1-\alpha}N\exp\left(-\frac{m}{2}\Delta_\sigma(c,\eta)^2\right).
\end{equation}

\label{lem:renyi_onebit_mismatch_explicit}
Let \(R_0\) and \(S_0\) be two probability distributions defined on the unit sphere \(\mathbb S^{n-1}\). Assume that \(R_0\) and \(S_0\) satisfy the spherical Wasserstein-\(\infty\) mismatch condition $\mathcal W_{\infty,\mathrm{geo}}(R_0,S_0)\le \epsilon,$ where \(0<\epsilon\le 1\). Let \(D\) be a probability distribution on \(\mathbb S^{n-1}\). Let \(x^*\sim R_0, z^*\sim S_0\). Let \(\Pi\) be a coupling of \(R_0\) and \(S_0\) such that, for
\((x^*,z^*)\sim\Pi\), \(\mathrm{d}_{\mathrm{S}}(x^*,z^*)\le \epsilon\) almost surely. Let \(\widehat x\) and \(\widehat z\) be posterior samples with respect to
the model prior \(D\), conditioned on \((A,y)\) and \((A,u)\). Consider the noisy one-bit measurement model
\begin{equation}
    y=\operatorname{sign}(Ax^*+\xi),
    \qquad
    u=\operatorname{sign}(Az^*+\xi'),
\end{equation}
where \(A_{ij}\sim\mathcal N(0,1)\), \(\xi,\xi'\sim \mathcal N(0,\sigma^2 I_m)\), and \(A\), \(\xi\), and \(\xi'\)
are mutually independent.
Let $r_\epsilon=2\sin\left(\frac{\pi\epsilon}{2}\right)$.
Then, for any $d>0$ and any parameter $
0<\lambda\le
\min\left\{
1,\,
\frac{\sigma^2}{3r_{\epsilon}^2}
\right\}
$, we have
\begin{equation}
\label{eq:explicit_renyi_mismatch_bound}
    \Pr\left(
    \mathrm{d}_{\mathrm{S}}(x^*,\widehat x)\ge d+\epsilon
    \right)
    \le
    \left(
    1-\frac{\lambda(1+\lambda)r_\epsilon^2}{\sigma^2}
    \right)^{-\frac{m}{2(1+\lambda)}}
    \Pr\left(
    \mathrm{d}_{\mathrm{S}}(z^*,\widehat z)\ge d
    \right)^{\frac{\lambda}{1+\lambda}}.
\end{equation}

\label{thm:one_bit_sphere_lower_bound}
Let $R$ be a prior distribution defined on the high dimensional unit Euclidean sphere $\mathbb{S}^{n-1}$, where $x^* \sim R$. Define the recovery accuracy \(\eta\in(0,\frac{1}{3})\), suppose that $\delta<0.1$ and that there exists a recovery algorithm capable of outputting $\widehat{x} \in \mathbb{S}^{n-1}$ based solely on the observation $y$ and the matrix $A$, such that:
\begin{equation}
    \Pr\left(d_{S}(\widehat{x}, x^*) \le \eta\right) \ge 1-\delta.
\end{equation}
If $A$ is a deterministic matrix, then the number of measurements $m$ must satisfy:
\begin{equation}
    m \ge \frac{0.072\pi\sigma^2}{2(\log 2)\|A\|_{2,\infty}^2} \left( \log \mathrm{Cov}_{3\eta, 4\delta}(R) + \log(6\delta)-25 \right).
\end{equation}
If $A_{ij}\sim \mathcal N(0,1)$, then the number of measurements $m$ must satisfy:
\begin{equation}
    m \ge \frac{0.072\pi}{2(\log 2)\arcsin\left(\frac{1}{1+\sigma^2}\right)} \left( \log \mathrm{Cov}_{3\eta, 4\delta}(R) + \log(6\delta)-25\right).
\end{equation}

\label{lemma:oneupper}
Assume that the measurement process is $y = \operatorname{sign}(Ax^*+\xi)$, where $\xi\sim\mathcal N(0,\sigma^2I_m)$. If $A$ is a deterministic matrix, we have
\begin{equation}
    I(y; x^*) \le \frac{2m\log 2}{\pi \sigma^2} \|A\|_{2,\infty}^2.
\end{equation}
If $A_{ij}\sim\mathcal N(0,1)$, we have
\begin{equation}
   I(y; x^* | A) \le \frac{2m \log 2}{\pi} \arcsin\left(\frac{1}{1+\sigma^2}\right).
\end{equation}

\label{lemma:spherefano_new}
Let $(x, \widehat{x})$ be random variables with a joint distribution on the unit Euclidean sphere $\mathbb{S}^{n-1} \times \mathbb{S}^{n-1}$, where $x \sim R$, and suppose that the estimator satisfies
\begin{equation}
    \Pr\left(d_{S}(x, \widehat{x}) \le \eta\right) \ge 1-\delta.
\end{equation}
Assuming $\delta$ is sufficiently small, then for any $\tau \in (0, 1-2\delta)$, the following holds:
\begin{equation}
    (1-\delta)\tau(1-2\delta)\log \mathrm{Cov}_{3\eta, \tau+3\delta}(R) \le I(x; \widehat{x}) + 2(1-\delta).
\end{equation}

(Adopted from~\citep[Lemma A.1]{jalal2021instance}) 
\label{lem:cov_lemma}
Let $R, P$ be arbitrary distributions on $\mathbb{S}^{n-1}$. Let $p \ge 1$ and $\eta, \rho, \delta > 0$ be parameters.
If $\mathcal{W}_{p,geo}(R, P) \le \rho$ and $\min\{\log \mathrm{Cov}_{\eta, \delta}(P), \log \mathrm{Cov}_{\eta, \delta}(R)\} \le k$, then there exist distributions $R', R'', P', P''$ and a finite discrete distribution $Q$ with a support size $|supp(Q)| \le e^k$, satisfying the following conditions:

\begin{enumerate}
\item $\min \{\mathcal{W}_{\infty,geo}(P', Q), \mathcal{W}_{\infty,geo}(R', Q)\} \le \eta$.
\item $\mathcal{W}_{\infty,geo}(R', P') \le \frac{\rho}{\delta^{1/p}}$.
\item $P = (1-2\delta)P' + (2\delta)P''$ and $R = (1-2\delta)R' + (2\delta)R''$.
\end{enumerate}

By assumption, \(\mathcal W_{p,\mathrm{geo}}(R,P)\le \rho\),
and we also have
\begin{equation}
\min\{
\log \mathrm{Cov}_{\eta,\delta}(P),
\log \mathrm{Cov}_{\eta,\delta}(R)
\}
\le \log \mathrm{Cov}_{\eta,\delta}(R).
\end{equation}
By \(\Cref{lem:cov_lemma}\), there exist probability distributions
\(R'\), \(R''\), \(P'\), \(P''\), and a finite discrete distribution \(Q\), such that
\begin{equation}
|\operatorname{supp}(Q)|\le \mathrm{Cov}_{\eta,\delta}(R),
\end{equation}
and
\begin{equation}
\label{eq:good_winfty_mismatch_cn}
\mathcal W_{\infty,\mathrm{geo}}(R',P')
\le
\frac{\rho}{\delta^{1/p}}
=
\varepsilon_\delta .
\end{equation}
Moreover, \(R\) and \(P\) can be decomposed as
\begin{equation}
\label{eq:mixture_decomp_cn}
R=(1-2\delta)R' + 2\delta R'',
\qquad
P=(1-2\delta)P' + 2\delta P'' .
\end{equation}
In addition, the lemma also guarantees that
\begin{equation}
\label{eq:min_q_close_cn}
\min\{
\mathcal W_{\infty,\mathrm{geo}}(P',Q),
\mathcal W_{\infty,\mathrm{geo}}(R',Q)
\}
\le \eta .
\end{equation}

This step converts the global \(W_p\) mismatch into a
\(W_\infty\) mismatch on the good parts. The residual components \(R''\) and \(P''\)
may be arbitrary distributions, but their weights in the original distributions are at most \(2\delta\).


We next prove that \(P'\) can be fully covered by at most \(\mathrm{Cov}_{\eta,\delta}(R)\) spherical caps of radius \(\bar\eta\).

By Eq.~\eqref{eq:min_q_close_cn}, there are two cases.

The first case is \(\mathcal W_{\infty,\mathrm{geo}}(P',Q)\le \eta\).


By the definition of the \(W_\infty\) distance, there exists a coupling
\(\gamma\in\Pi(P',Q)\) such that
\begin{equation}
    \mathrm{d}_{\mathrm{S}}(x,q)\le \eta
    \qquad \gamma\text{-a.s.}
\end{equation}
Since \(Q\) is a finite discrete distribution and the second marginal of \(\gamma\) is \(Q\),
we have
\begin{equation}
    \gamma\left(
    \left\{(x,q): q\in \operatorname{supp}(Q),
    \ \mathrm{d}_{\mathrm{S}}(x,q)\le \eta \right\}
    \right)=1 .
\end{equation}
Therefore,
\begin{equation}
    P'\left(
    \bigcup_{q\in\operatorname{supp}(Q)}
    \mathcal B(q,\eta)
    \right)=1 .
\end{equation}
By the definition of the \((\eta,0)\)-covering number, it follows that
\begin{equation}
    \operatorname{Cov}_{\eta,0}(P')
    \le |\operatorname{supp}(Q)|
    \le \mathrm{Cov}_{\eta,\delta}(R) .
\end{equation}
Moreover, since \(\bar\eta\ge \eta\), we obtain
\begin{equation}
    \operatorname{Cov}_{\bar\eta,0}(P')
    \le
    \operatorname{Cov}_{\eta,0}(P')
    \le \mathrm{Cov}_{\eta,\delta}(R) .
\end{equation}

The second case is \(\mathcal W_{\infty,\mathrm{geo}}(R',Q)\le \eta\).


Combining this with Eq.~\eqref{eq:good_winfty_mismatch_cn} and using the triangle inequality for
the \(W_\infty\) distance, we have
\begin{equation}
    \mathcal W_{\infty,\mathrm{geo}}(P',Q)
    \le
    \mathcal W_{\infty,\mathrm{geo}}(P',R')
    +
    \mathcal W_{\infty,\mathrm{geo}}(R',Q)
    \le
    \varepsilon_\delta+\eta
    =
    \bar\eta .
\end{equation}
Thus, there exists a coupling
\(\tilde\gamma\in\Pi(P',Q)\) such that
\begin{equation}
    \mathrm{d}_{\mathrm{S}}(x,q)\le \bar\eta
    \qquad \tilde\gamma\text{-a.s.}
\end{equation}
Similarly, we obtain
\begin{equation}
    P'\left(
    \bigcup_{q\in\operatorname{supp}(Q)}
    \mathcal B(q,\bar\eta)
    \right)=1 .
\end{equation}
Hence,
\begin{equation}
    \operatorname{Cov}_{\bar\eta,0}(P')
    \le |\operatorname{supp}(Q)|
    \le \mathrm{Cov}_{\eta,\delta}(R) .
\end{equation}

Combining the two cases, we have
\begin{equation}
\label{cov_pandR}
    \operatorname{Cov}_{\bar\eta,0}(P')\le \mathrm{Cov}_{\eta,\delta}(R) .
\end{equation}
Moreover, defining
\begin{equation}
    G_P:=
    \bigcup_{q\in\operatorname{supp}(Q)}
    \mathcal B(q,\bar\eta),
\end{equation}
the previous argument shows that
\begin{equation}
    P'(G_P)=1.
\end{equation}
Since \(P=(1-2\delta)P'+2\delta P''\), it follows that
\begin{equation}
    P(G_P)\ge 1-2\delta .
\end{equation}
Consequently,
\begin{equation}
    \operatorname{Cov}_{\bar\eta,2\delta}(P)\le \mathrm{Cov}_{\eta,\delta}(R) .
\end{equation}


Consider the following matched good-component experiment:
\begin{equation}
z^*\sim P',
\qquad
u=\operatorname{sign}(Az^*+\xi'),
\end{equation}
where \(\xi'\sim\mathcal N(0,\sigma^2I_m)\), and \(\xi'\) is independent of all other random variables.
Let
\(
\widehat z
\sim
P(\cdot| u,A)
\)
be the posterior sampling estimator based on the full learned prior distribution\(P\).

By Eq.~\eqref{cov_pandR}, \(P'\) can be fully covered by at most \(\mathrm{Cov}_{\eta,\delta}(R)\)
spherical caps of radius \(\bar\eta\). Moreover, by Eq.~\eqref{eq:mixture_decomp_cn},
\[
P=(1-2\delta)P' + 2\delta P'' .
\]
Therefore, applying \(\Cref{lemma:orup}\) with full prior \(P\), good component \(P'\),
bad component \(P''\), mixture parameter \(\alpha=2\delta\), covering radius
\(\bar\eta\), we get \(N=|\operatorname{supp}(Q)|\le \mathrm{Cov}_{\eta,\delta}(R)\).Then we obtain
\begin{align}
\label{eq:matched_pprime_bound_cn}
\Pr_{z^*\sim P',A,\xi',\widehat{z}}\left(
\mathrm{d}_{\mathrm{S}}(z^*,\widehat z)
\ge
(c+1)\bar\eta
\right)
&\le
\frac{1}{1-2\delta}
\mathrm{Cov}_{\bar\eta,2\delta}(P)
\exp\!\left(
-\frac m2\Delta_\sigma(c,\bar\eta)^2
\right)
\nonumber,\\
&\le
\frac{1}{1-2\delta}
\exp\!\left(
\log \mathrm{Cov}_{\eta,\delta}(R)-\frac m2\Delta_\sigma(c,\bar\eta)^2
\right)
\nonumber,\\
&=
\exp\!\left(
\log \mathrm{Cov}_{\eta,\delta}(R)+\log\frac{1}{1-2\delta}
-\frac m2\Delta_\sigma(c,\bar\eta)^2
\right).
\end{align}



By Eq.~\eqref{eq:good_winfty_mismatch_cn}, we have
\begin{equation}
\mathcal W_{\infty,\mathrm{geo}}(R',P')
\le
\varepsilon_\delta .
\end{equation}
Therefore, there exists a coupling \(\Pi\in\Pi(R',P')\) such that, if \((x^*,z^*)\sim \Pi\),
then almost surely
\begin{equation}
\mathrm{d}_{\mathrm{S}}(x^*,z^*)\le \varepsilon_\delta .
\end{equation}

Now consider two one-bit observation models:
\begin{equation}
y=\operatorname{sign}(Ax^*+\xi),
\qquad
u=\operatorname{sign}(Az^*+\xi').
\end{equation}
Here \(x^*\sim R'\) and \(z^*\sim P'\). The posterior samples are both taken
with respect to the full learned prior distribution\(P\), namely
\begin{equation}
\widehat x\sim P(\cdot| y,A),
\qquad
\widehat z\sim P(\cdot| u,A).
\end{equation}
Applying
\Cref{lem:renyi_onebit_mismatch_explicit} with
\[
R_0=R',
\qquad
S_0=P',
\qquad
D=P,
\qquad
\epsilon=\varepsilon_\delta,
\qquad
d=(c+1)\bar\eta,
\]
we obtain
\begin{align}
\label{eq:renyi_transfer_step_cn}
&
\Pr_{x^*\sim R',A,\xi,\widehat{x}}\left(
\mathrm{d}_{\mathrm{S}}(x^*,\widehat x)
\ge
(c+1)\bar\eta+\varepsilon_\delta
\right)
\nonumber\\
&\qquad\le
\left(
1-
\frac{\lambda(1+\lambda)r_{\varepsilon_\delta}^2}{\sigma^2}
\right)^{-\frac{m}{2(1+\lambda)}}
\Pr_{z^*\sim P',A,\xi',\widehat{z}}\left(
\mathrm{d}_{\mathrm{S}}(z^*,\widehat z)
\ge
(c+1)\bar\eta
\right)^{\frac{\lambda}{1+\lambda}} .
\end{align}


Substituting Eq.~\eqref{eq:matched_pprime_bound_cn} into
Eq.~\eqref{eq:renyi_transfer_step_cn}, we get
\begin{align}
\label{eq:good_part_final_bound_cn}
&
\Pr_{x^*\sim R',A,\xi,\widehat{x}}\left(
\mathrm{d}_{\mathrm{S}}(x^*,\widehat x)
\ge
(c+1)\bar\eta+\varepsilon_\delta
\right)
\nonumber\\
&\qquad\le
\left(
1-
\frac{\lambda(1+\lambda)r_{\varepsilon_\delta}^2}{\sigma^2}
\right)^{-\frac{m}{2(1+\lambda)}}
\exp\!\left(
\frac{\lambda}{1+\lambda}
\left(
\log \mathrm{Cov}_{\eta,\delta}(R)+\log\frac{1}{1-2\delta}
-\frac m2\Delta_\sigma(c,\bar\eta)^2
\right)
\right).
\end{align}
For each realization of \(A\), define
\begin{align}
G(A)
:=
\Pr_{x^*\sim R',\xi,\widehat{x}| A}
\left(
\mathrm{d}_{\mathrm{S}}(x^*,\widehat x)
\ge
(c+1)\bar\eta+\varepsilon_\delta
\right).
\end{align}
Then Eq.~\eqref{eq:good_part_final_bound_cn} gives
\begin{align}
\mathbb E_A\left[G(A)\right]
\le
\left(
1-
\frac{\lambda(1+\lambda)r_{\varepsilon_\delta}^2}{\sigma^2}
\right)^{-\frac{m}{2(1+\lambda)}}
\exp\!\left(
\frac{\lambda}{1+\lambda}
\left(
\log \mathrm{Cov}_{\eta,\delta}(R)+\log\frac{1}{1-2\delta}
-\frac m2\Delta_\sigma(c,\bar\eta)^2
\right)
\right).
\end{align}
By Markov's inequality, for every \(\beta\in(0,1)\), we obtain that, with probability at least \(1-\beta\) over \(A\),
\begin{align}
\label{eq.173}
&
\Pr_{x^*\sim R',\xi,\widehat{x}| A}
\left(
\mathrm{d}_{\mathrm{S}}(x^*,\widehat x)
\ge
(c+1)\bar\eta+\varepsilon_\delta
\right)
\nonumber\\
&\qquad\le
\frac{1}{\beta}
\left(
1-
\frac{\lambda(1+\lambda)r_{\varepsilon_\delta}^2}{\sigma^2}
\right)^{-\frac{m}{2(1+\lambda)}}
\exp\!\left(
\frac{\lambda}{1+\lambda}
\left(
\log \mathrm{Cov}_{\eta,\delta}(R)+\log\frac{1}{1-2\delta}
-\frac m2\Delta_\sigma(c,\bar\eta)^2
\right)
\right).
\end{align}



By the decomposition Eq.~\eqref{eq:mixture_decomp_cn}, we have
\begin{equation}
R=(1-2\delta)R' + 2\delta R'' .
\end{equation}
Therefore, for every fixed realization of \(A\), the probability that the true signal \(x^*\) comes from the residual component \(R''\) is
\(2\delta\). For any event \(\mathcal E\), we have
\begin{equation}
\Pr_{x^*\sim R,\xi,\widehat{x}| A}(\mathcal E)
\le
2\delta+
\Pr_{x^*\sim R',\xi,\widehat{x}| A}(\mathcal E).
\end{equation}
Let
\begin{equation}
\mathcal E
=
\left\{
\mathrm{d}_{\mathrm{S}}(x^*,\widehat x)
\ge
(c+1)\bar\eta+\varepsilon_\delta
\right\}.
\end{equation}
Combining this with Eq.~\eqref{eq.173}, we obtain that, with probability at least \(1-\beta\) over \(A\),
\begin{align}
&
\Pr_{x^*\sim R,\xi,\widehat{x}| A}\left(
\mathrm{d}_{\mathrm{S}}(x^*,\widehat x)
\ge
(c+1)\bar\eta+\varepsilon_\delta
\right)
\nonumber\\
&\qquad\le
2\delta
+
\frac{1}{\beta}\left(
1-
\frac{\lambda(1+\lambda)r_{\varepsilon_\delta}^2}{\sigma^2}
\right)^{-\frac{m}{2(1+\lambda)}}
\exp\!\left(
\frac{\lambda}{1+\lambda}
\left(
\log \mathrm{Cov}_{\eta,\delta}(R)+\log\frac{1}{1-2\delta}
-\frac m2\Delta_\sigma(c,\bar\eta)^2
\right)
\right).
\end{align}

This completes the proof.

\label{claim421}
    For a standard normal random variable $Z \sim \mathcal{N}(0,1)$, where $\Phi(\cdot)$ is the standard normal cumulative distribution function, we have:
\begin{equation}
    \mathbb{E}_{Z}\left[\left(\Phi(cZ) - \frac{1}{2}\right)^2\right] = \frac{1}{2\pi} \arcsin\left(\frac{c^2}{1+c^2}\right) .
\end{equation}

We introduce two new standard normal random variables $U_1, U_2 \sim \mathcal{N}(0,1)$ that are mutually independent and independent of $Z$.
Then, conditioned on $Z$:
\begin{equation}
    \Phi(cZ) = \Pr\left(U_1 \le cZ | Z\right) = \Pr\left(U_1 - cZ \le 0 | Z\right),
\end{equation}
\begin{equation}
\Phi(cZ)^2 = \Pr\left(U_1 \le cZ, U_2 \le cZ | Z\right) = \Pr\left(U_1 - cZ \le 0, U_2 - cZ \le 0 | Z\right).
\end{equation}
Define the random variables: $W_1 = U_1 - cZ$, $W_2 = U_2 - cZ$. Since $U_1, U_2, Z\sim\mathcal N(0,1)$, $W_1$ and $W_2$ follow a joint zero-mean bivariate normal distribution.
By the additivity of Gaussian distributions, we have
\begin{equation}
    \mathrm{Var}(W_1) = \mathrm{Var}(U_1) + c^2\mathrm{Var}(Z) = 1 + c^2.
\end{equation}
\begin{equation}
    \mathrm{Cov}(W_1, W_2) = \mathbb{E}[(U_1 - cZ)(U_2 - cZ)] = c^2 \mathbb{E}[Z^2] = c^2.
\end{equation}
    Therefore, the correlation coefficient between $W_1$ and $W_2$ is:
\begin{align}
    \rho &= \frac{\mathrm{Cov}(W_1, W_2)}{\sqrt{\mathrm{Var}(W_1)\mathrm{Var}(W_2)}},\\
\label{Eq.26}
    &= \frac{c^2}{1+c^2}.
\end{align}
For joint bivariate normal variables with mean $0$ and correlation coefficient $\rho$, the probability that both are simultaneously less than or equal to $0$ is strictly given by the orthant probability formula for the standard bivariate normal distribution~\cite{o2014analysis}:
\begin{equation}
\label{Eq.22}
    \Pr\left(W_1 \le 0, W_2 \le 0\right) = \frac{1}{4} + \frac{1}{2\pi} \arcsin(\rho).
\end{equation}
Combining the above equations, we have:
\begin{align}
     \mathbb{E}_{Z}\left[\left(\Phi(cZ) - \frac{1}{2}\right)^2\right] &= \mathbb{E}_{Z}[\Phi(cZ)^2] - \mathbb{E}_{Z}[\Phi(cZ)] + \frac{1}{4},\\
     &=\frac{1}{4} + \frac{1}{2\pi} \arcsin(\rho)-\frac{1}{2}+ \frac{1}{4},\\
     &=\frac{1}{2\pi} \arcsin(\frac{c^2}{1+c^2}).
\end{align}

\label{lemma:4.3}
Consider the setting of \Cref{thm:one_bit_sphere_lower_bound}. If the measurement matrix $A$ is deterministic, we have:
\begin{equation}
    I(x^*; \widehat{x}) \le I(y; x^*).
\end{equation}

If $A$ is a Gaussian matrix, then:
\begin{equation}
    I(x^*; \widehat{x}) \le I(y; x^*|A).
\end{equation}

\label{lemma:B3_metric}
Let $Q$ be a distribution defined on a finite discrete set $S$ containing $N$ points. Assume there exists a sufficiently large integer $N_2$ such that for each $u$ in the support, $Q(u) = j \alpha$, where $j \in \mathbb{N}$, and the quantization step is $\alpha := 1/N_2$. 
Let $(x, \widehat{x})$ be jointly distributed, where $x \sim Q$, and $\widehat{x}$ lies in an arbitrary countable set. If the recovery condition is satisfied:
\begin{equation}
    \Pr\left(d(x, \widehat{x}) \le \epsilon\right) \ge 1-\delta.
\end{equation}
Then we have:
\begin{equation}
    \tau(1-\delta)\log \mathrm{Cov}_{2\epsilon, \tau+\delta}(Q) \le I(x; \widehat{x}) + 2.
\end{equation}
